}
/// <summary>Shuffles complete independent blocks without extending any source or destination access.</summary>
/// <param name = "input">The validated input cursor.</param>
/// <param name = "output">The validated output cursor.</param>
/// <param name = "blocks">The number of complete blocks still available.</param>
/// <param name = "inputStep">The input block stride.</param>
/// <param name = "outputStep">The output block stride.</param>
/// <param name = "wideInput">Whether a block has two input vectors.</param>
/// <param name = "wideOutput">Whether a block has two output vectors.</param>
/// <param name = "mask0">The first shuffle mask.</param>
/// <param name = "mask1">The second shuffle mask.</param>
/// <param name = "mask2">The third shuffle mask.</param>
/// <param name = "mask3">The fourth shuffle mask.</param>
[MethodImpl(MethodImplOptions.NoInlining)]
internal static unsafe void Copy256(ref byte input, ref byte output, ref nint blocks, nint inputStep, nint outputStep, bool wideInput, bool wideOutput, global::Unity.Burst.Intrinsics.v128 mask0, global::Unity.Burst.Intrinsics.v128 mask1, global::Unity.Burst.Intrinsics.v128 mask2, global::Unity.Burst.Intrinsics.v128 mask3)
{
    var m0 = NativeVectorOps.Join256(mask0, mask0);
    var m1 = NativeVectorOps.Join256(mask1, mask1);
    var m2 = NativeVectorOps.Join256(mask2, mask2);
    var m3 = NativeVectorOps.Join256(mask3, mask3);
    for (; blocks >= 2; blocks -= 2)
    {
        var low = NativeVectorOps.Join256(NativeVectorOps.Load128(ref input, (nuint)(0 * inputStep + 0)), NativeVectorOps.Load128(ref input, (nuint)(1 * inputStep + 0)));
        var high = wideInput ? NativeVectorOps.Join256(NativeVectorOps.Load128(ref input, (nuint)(0 * inputStep + 16)), NativeVectorOps.Load128(ref input, (nuint)(1 * inputStep + 16))) : default;
        var first = NativeVectorOps.Shuffle256(low, m0);
        if (wideInput)
            first = NativeVectorOps.Or256(first, NativeVectorOps.Shuffle256(high, m1));
        var second = wideOutput ? NativeVectorOps.Shuffle256(low, m2) : default;
        if (wideOutput && wideInput)
            second = NativeVectorOps.Or256(second, NativeVectorOps.Shuffle256(high, m3));
        NativeVectorOps.Store128(first.Lo128, ref output, (nuint)(0 * outputStep));
        if (wideOutput)
            NativeVectorOps.Store128(second.Lo128, ref output, (nuint)(0 * outputStep + 16));
        NativeVectorOps.Store128(first.Hi128, ref output, (nuint)(1 * outputStep));
        if (wideOutput)
            NativeVectorOps.Store128(second.Hi128, ref output, (nuint)(1 * outputStep + 16));
        input = ref Unsafe.Add(ref input, inputStep * 2);
        output = ref Unsafe.Add(ref output, outputStep * 2);
    }
}
}
