            return ((Vector128.LoadUnsafe(ref chars) | Vector128.LoadUnsafe(ref chars, (nuint)(uint)(length - 8))) & Vector128.Create((ushort)0xFF00)) == Vector128<ushort>.Zero;
        if (length >= 4)
